with with_windows as (select id, dept_name, rank() over (partition by dept_name order by budget nulls last) as budget_rank, lag(budget, 2) over w_running as prev_budget, row_number() over (partition by location order by budget desc, id) as event_seq, sum(budget) over w_running_2 as running_budget, row_number() over w_grp as seq_no from departments window w_running as (order by budget, id), w_running_2 as (order by budget, id rows between unbounded preceding and current row), w_grp as (partition by dept_name order by budget, id)) select seq_no, case when prev_budget >= 3203000 then 'HIGH' else 'LOW' end as prev_budget_tier, max(prev_budget) as max_prev_budget, approx_percentile(seq_no, 0.9) as seq_no_p90, size(collect_set(dept_name)) as num_dept_names, grouping(seq_no) as grouping_id from with_windows group by cube (seq_no, case when prev_budget >= 3203000 then 'HIGH' else 'LOW' end) having approx_percentile(seq_no, 0.9) >= 0;
